typedef struct {pthread_mutex_t mutex;pthread_cond_t condition;unsigned count;bool deleted;} semaphore_t;
typedef struct {pthread_t thread;void(*entry)(void*);void*argument;} task_t;
static atomic_uint g_create_count,g_fail_create,g_abort_count,g_publish_count,g_session;
