static void scenario_hold_success_retry_fifo(void){puts("input-production: hold-success-retry-fifo");start_case();atomic_store(&g_retry_once,true);assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_DOWN,VK_INPUT_KEY_K4,0)));wait_uint(&g_release_count,1U);assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_UP,VK_INPUT_KEY_K4,1600)));assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_CLICK,VK_INPUT_KEY_K4,1600)));assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_DOWN,VK_INPUT_KEY_K1,0)));wait_uint(&g_stop_count,1U);wait_sent(4U);pthread_mutex_lock(&g_sent_mutex);assert(g_sent[0].value.kind==VK_USB_BUTTON_DOWN&&g_sent[0].value.has_session_id);assert(g_sent[1].value.kind==VK_USB_BUTTON_UP&&g_sent[1].value.session_id==g_sent[0].value.session_id);assert(g_sent[2].value.kind==VK_USB_BUTTON_CLICK&&g_sent[2].value.session_id==g_sent[0].value.session_id);assert(g_sent[3].value.key==VK_USB_KEY_K1);pthread_mutex_unlock(&g_sent_mutex);finish_epoch(9U);}
