static void scenario_prepare_failure_sessionless(void){puts("input-production: prepare-failure-sessionless");start_case();atomic_store(&g_prepare_result,ESP_FAIL);assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_DOWN,VK_INPUT_KEY_K4,0)));assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_UP,VK_INPUT_KEY_K4,42)));assert(vk_input_test_enqueue_transition(transition(VK_INPUT_TRANSITION_CLICK,VK_INPUT_KEY_K4,42)));wait_sent(3U);pthread_mutex_lock(&g_sent_mutex);for(size_t i=0;i<3U;++i)assert(!g_sent[i].value.has_session_id);pthread_mutex_unlock(&g_sent_mutex);wait_uint(&g_error_count,1U);finish_epoch(9U);}
