static void scenario_mailboxes_full_reserved_abort_supersession(void){puts("input-production: mailbox-full-reserved-abort-supersession");start_case();assert(vk_input_test_fill_ordinary_mailboxes());vk_usb_input_lifecycle_ack_t old={0},fresh={0};vk_usb_input_lifecycle_sink_t a={.publish=publish,.context=&old},b={.publish=publish,.context=&fresh};vk_usb_input_lifecycle_request_t r={.kind=VK_USB_INPUT_LIFECYCLE_LEASE_EXPIRED,.token=11U,.old_epoch=9U,.proposed_epoch=0U,.lifecycle_generation=12U};assert(g_lifecycle.begin(g_lifecycle.context,&r,&a)==VK_USB_INPUT_LIFECYCLE_ACCEPTED);r.kind=VK_USB_INPUT_LIFECYCLE_STOPPING;r.token=13U;r.lifecycle_generation=14U;assert(g_lifecycle.begin(g_lifecycle.context,&r,&b)==VK_USB_INPUT_LIFECYCLE_ACCEPTED);wait_uint(&g_publish_count,2U);assert(fresh.token==13U&&fresh.result==VK_USB_INPUT_LIFECYCLE_QUIESCENT);assert(atomic_load(&g_abort_count)==1U);assert(vk_input_stop()==ESP_OK);assert(vk_input_deinit()==ESP_OK);}
