static void scenario_join_timeout_retains_ownership(void){puts("input-production: join-timeout-retains-ownership");start_case();finish_epoch(9U);/* Re-run with an injected bounded join timeout. */reset();assert(vk_input_init()==ESP_OK);assert(vk_input_start()==ESP_OK);(void)begin_epoch(9U);vk_usb_input_lifecycle_ack_t ack={0};vk_usb_input_lifecycle_sink_t sink={.publish=publish,.context=&ack};vk_usb_input_lifecycle_request_t r={.kind=VK_USB_INPUT_LIFECYCLE_STOPPING,.token=31U,.old_epoch=9U,.proposed_epoch=0U,.lifecycle_generation=32U};assert(g_lifecycle.begin(g_lifecycle.context,&r,&sink)==VK_USB_INPUT_LIFECYCLE_ACCEPTED);wait_uint(&g_publish_count,2U);vk_input_test_force_join_timeout(true);assert(vk_input_stop()==ESP_ERR_TIMEOUT);assert(vk_input_test_started());assert(vk_input_deinit()==ESP_ERR_INVALID_STATE);vk_input_test_force_join_timeout(false);assert(vk_input_stop()==ESP_OK);assert(vk_input_deinit()==ESP_OK);}
